-- 2406 🏋️ Exercises from the book "coaching-combination-play-from-build-up-to-finish" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-combination-play-from-build-up-to-finish');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Midfield 3 rotation pass and move', 'passing_unopposed', 'unopposed', 'in_possession', 21, 23, 'Rotation of the Midfield 3 in a Pass & Move Practice (Unopposed)', NULL, 'Rotating midfield trio moves as a unit to lose markers and play quick one-twos with players driving forward from both sides.', 'Half pitch; 3 midfielders on 3 cones forming a triangle in the centre; queues with a ball each start at cone gates near the edge of the box on both flanks, running towards the halfway line.', 'Players on both sides dribble forward at the same time and play a one-two with one of the rotating midfielders, who rotate (anti-clockwise) after every pass; after the first-time bounce pass the runner carries on at speed to the halfway line, turns and dribbles back to the start gate.', 'Midfielders play first-time bounce passes; rotate the 3 midfielders out regularly.', 'Add one passive red defender pressing the midfield 3 (3v1), then a second passive defender; then semi-active pressing; then fully active defenders trying to intercept. Further progression: the more advanced midfielder (No.10) times an arced run into space cleared by the deepest midfielder to receive a second-option pass and bounce it back (3v2).', 'Well-timed movements; weight passes into the runner''s path; hand signals for where you want it; keep a triangle; open/half-turned body shape; arc runs to keep security in zone 14; heads up; second-option pass beyond the nearest man is the more attacking choice; keep passes on the ground with ping.', '3 midfielders + 2 queues of runners (up to 3 v 2 with defenders)', 9, NULL, 'Half a full-sized pitch', NULL, NULL, NULL, false, false, true, NULL, 10),
  ('Pass through a triangle network', 'passing_unopposed', 'unopposed', 'in_possession', 27, 27, 'Exploring the Second Option Pass', NULL, 'Pass and move between cones, first to the nearest teammate and then picking the second-option pass beyond him.', 'Half pitch covered in a network of cones about 10 yards apart forming triangles; players spread on the cones; start with 1-2 balls, building to 4.', 'Players pass and move freely between the cones, initially playing the first-option pass to the nearest teammate, then moving to a free cone. Anyone without a pass for 3 seconds moves to a new free position.', 'Max 2 touches (control and pass); rolling subs if needed.', 'Add 2 passive opponents who drift around blocking lanes; then challenge players to pass through a triangle to the second-option player (beyond the nearest, more advanced or arriving).', 'Check away to lose a marker before receiving; time runs into free space; signal where you want the ball; ping second-option passes along the ground.', 'Approx 12-14 players', NULL, NULL, 'Half pitch, cones 10 yards apart', NULL, NULL, NULL, false, true, false, NULL, 20),
  ('Position-specific pass and move to goal', 'passing_unopposed', 'unopposed', 'in_possession', 28, 30, 'PROGRESSION: Position Specific Pass & Move Combinations', NULL, 'Rehearse build-up passing patterns between team positions from the keeper to a winger who finishes.', 'Half pitch split into 2 equal halves, each with 5 cones for centre back, central midfielder, full back, attacking midfielder/forward and winger; a full-sized goal and keeper at each end; 14 outfield players.', 'Both keepers start at once by passing to the CB; the ball moves through the positions in sequence (1-5) and each player follows his pass to the next cone; the winger shoots on goal and then runs round to join the group on the other side. Continuous, anti-clockwise.', 'Max 2 touches (control and pass), adjust to ability; players check away from the cone before receiving.', 'Change the sequence to mix first-option passes (keeper to CM, bounce to FB, set to CB) with a penetrating second-option pass (CB to winger, set to AM/F who shoots); then start from a gate on the side: keeper to full back, full back sets back to centre back, CB plays second-option pass into the forward, forward sets to midfielder, midfielder plays the winger cutting inside to shoot.', 'Check away to create space; signal which foot you want it on; half-turned body shape; line up with the incoming pass to play first time; crisp, weighted passes on the ground.', '14 outfield + 2 GKs', 16, 16, 'Half a full-sized pitch split into 2 halves', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('7v6 build-up from keeper to cone goals', 'phase_of_play', 'opposed', 'in_possession', 31, 31, 'PROGRESSION: Building Up Play from the Goalkeeper with Midfield Rotations in a Game Specific Practice', NULL, 'Play out from the keeper on one flank using the rotating midfield 3 against pressure.', 'Half pitch with one flank coned off; 2 cone goals (3 yards wide) on the halfway line; blue team = GK, 1 centre back, 1 full back, 3 rotating midfielders, 1 winger, 1 striker v 6 reds.', 'Blues build up from the keeper and try to dribble through one of the halfway-line cone goals; restart with a goal kick whenever the ball goes out.', 'Reds who win the ball have 10 seconds to score past the keeper.', 'Variation: cone off the other flank to work the opposite side. Start with reds pressing passively, then go fully competitive.', 'Good pass and move while keeping triangles; use a tactics board to show first and second option patterns; perform the coordinated movements from the board.', '7 (+GK) v 6', 14, NULL, 'Half a full-sized pitch with one flank coned off', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('9v6 midfield rotation build-up game', 'phase_of_play', 'overload', 'in_possession', 32, 32, 'PROGRESSION: Midfield Rotations to Build Up Play from the Goalkeeper in a Dynamic Game', NULL, 'Use a 3v2 midfield overload and rotations to find the spare man and play out to the halfway line.', 'Half pitch, full goal with keeper, 2 cone goals (3 yards wide) on halfway line, central box 25 x 20 yards; blues: 2 CBs, 2 FBs, 3 rotating midfielders, 2 wingers; reds: 2 strikers, 2 central midfielders, 2 wingers; flank cones mark full back and winger start spots.', 'Blue keeper starts; the midfield 3 rotate in the box (3v2) to free a man, and the team combines to dribble through a halfway cone goal for 1 point. Restart with a goal kick when the ball goes out.', '1 point per cone-goal dribble; reds have 10 seconds to score if they win it.', 'Reds press passively first, then full competitive pressure.', 'Pass and move to play out; midfield keeps a triangle and moves to free one man; body shape side-on with arced runs; time runs to link up.', '9 (+GK) v 6', 16, NULL, 'Half pitch; central box 25 x 20 yards', 22.9, 18.3, NULL, true, true, true, NULL, 50),
  ('''The Cut'' build-up game 9v5', 'phase_of_play', 'overload', 'in_possession', 39, 39, '''The Cut'' Movement Pattern & Combination Play in a Game Specific Practice', NULL, 'Play out from the keeper using ''The Cut'' (CB decoy run inside, full back drops down the line) combined with the midfield rotation.', 'Half pitch, full goal, 2 cone gates (3-4 yards) on halfway line; markers for start spots of back 4, midfield 3 and 2 wingers; blues 9 + GK v 5 reds (2 strikers, 2 wingers, 1 midfielder).', 'From a goal kick the reds press high; the keeper, full back or centre back calls ''Cut'', the CB runs diagonally inside across the striker, the FB drops down the line to receive side-on, midfield rotates, and the team combines to dribble through a cone gate.', 'Reds who win the ball have 10 seconds to score; restart from the keeper when the ball goes out.', 'Reds press passively without tackling at first, then go fully competitive.', 'Trigger the pattern with a ''Cut'' call; CB decoy run in front of the presser; FB drops down the line side-on; if the striker ignores the CB, keeper finds the CB in space; if he tracks him, ping it wide to the FB; disguise intentions; time movements to lose markers.', '9 (+GK) v 5', 15, NULL, 'Half a full-sized pitch', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Keeper distribution and support angles', 'goalkeeping', 'unopposed', 'in_possession', 47, 47, 'Goalkeeper Support Angles & Accurate Passing to Switch Play', NULL, 'Keeper practises ground and long distribution to build-up positions and moving wide of the post to support and switch play.', 'Half pitch with marked zones for target positions: A1 full backs dropping down the line, A2 centre backs at goal kicks, B1/B2 rotating midfielders, C1/C2 full back and winger goal-kick spots; target players (coaches/subs) stand in them.', 'Keeper plays a sequence of crisp ground passes to the target zones, then moves to offer a back-pass angle wide of the post; on receiving the return he opens up with his first touch and switches play to the opposite side or into midfield, or dribbles to switch.', 'Switch with 2 touches (control and pass) where possible.', 'Add a player who presses the keeper after the back pass; keeper must take a positive first touch away and recycle to the far side or go long.', 'Check supporters are ready before playing; first touch away from pressure; if no pressure, change direction with the ball then ping out to the far CB or FB; communicate to help teammates support. Can be used as the keeper''s pre-match warm-up.', '1 GK + target players', NULL, NULL, 'Half a full-sized pitch', NULL, NULL, NULL, false, true, false, NULL, 70),
  ('Switch play via keeper, 4 gates', 'phase_of_play', 'opposed', 'in_possession', 48, 48, 'Switching Play Through the Goalkeeper Using ''The Cut'' & ''The Switch'' (Game Specific Practice)', NULL, 'Play out against a high press using ''The Cut'' and switching play through the keeper to the weak side.', 'Half pitch with 4 cone gates (3 yards wide) on halfway line; blues = keeper, back four and midfield 3 (4, 8, 10); reds = 2 forwards, 2 wingers, 2 central midfielders; cones can mark start positions.', 'From a goal kick the blues try to play out and dribble through a gate; reds press high (strikers start central then press CBs, wingers press full backs, midfielders press the rotating midfielders). Blues use ''The Cut'' or a back pass to the keeper and a switch to the opposite CB/FB dropping down the line.', 'Start with passive pressing, then full pressure; option to make reds man-mark.', 'Passive to full high pressure; man-marking option.', 'Supporters ready as keeper looks up; CBs and FBs receive side-on; keeper''s first touch away from pressure and switch in 2 touches on the ground; if not pressed, change direction before pinging it to the far side; keeper communicates.', '8 (GK + 7) v 6', 14, NULL, 'Half a full-sized pitch', NULL, NULL, NULL, false, true, true, NULL, 80),
  ('Switching play with inverted wingers SSG', 'phase_of_play', 'overload', 'in_possession', 55, 55, NULL, NULL, 'Switch play quickly to trigger central midfield rotations and break through the opposition via a rotating attacking midfielder.', 'Half pitch, blue 8 (2 full backs, a 6, two 8/10s, two wingers, a 9) attack a goal and keeper against red 7 (back 4 near the box, 2 holding mids, 1 attacking mid); 3 red cone gates 3 yards wide on halfway line plus 5 blue cones.', 'A full back plays into the 6, which cues the central rotations and the far full back''s forward run; blues switch play and attack. Reds who win it have 6 seconds to counter and dribble through a halfway gate.', '1-2 touches; must start with a switch of play; must go through one of the 8/9/10 before attacking the goal; only one full back may push on at a time.', NULL, 'Good shape and support angles to switch flank to flank; central players rotate to lose markers; pass to create space for the far winger; two movements before receiving; striker moves opposite the ball to the blind side; timed runs into the box.', '8v7 (+GK)', 16, 16, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Switching play 7v7 with wide neutrals', 'small_sided_game', 'overload', 'in_possession', 56, 56, NULL, NULL, 'Switch play from one flank to the other before attacking the goal.', '40 x 60 yard pitch with a goal and keeper at each end and a marked side zone on each flank holding a neutral player; teams of 7 in a 3-2-1 or 2-2-2 shape.', 'Play starts with either keeper; the team in possession must get the ball to both wide neutrals (one on each side) before it may shoot. Both teams play under the same condition.', 'Neutrals limited to 3 touches and must stay in their side zones; both neutrals must touch the ball before a shot.', 'The neutral on the far side may leave his zone to attack the far post and score.', 'Defending team stays compact with pressure, cover and balance; build through the thirds; keepers involved in switching play.', '7v7 +2 neutrals (incl. GKs)', 16, 16, '40 x 60 yards', 54.9, 36.6, NULL, true, true, true, NULL, 100),
  ('Forwards push wide to open centre 7v7', 'small_sided_game', 'opposed', 'in_possession', 57, 58, NULL, NULL, 'Two forwards create width high up so midfielders can attack the central space, joining to make a 3v2.', '40 x 50 yards split into thirds with 8-10 yard side channels used only in the attacking third (no receiving in the middle-third channels); goals with keepers; 2-2-2 shape, 2v2 in each third.', 'Coach serves to a keeper; teams play through the thirds and once the ball reaches the attacking zone one midfielder may enter to make a 3v2. Defenders who win it attack the other way under the same conditions.', 'No corners or throw-ins, restart with the opposite keeper; only one midfielder may join the attacking third.', 'Variation (same set-up): the 2 forwards tuck inside to clear the flanks, and a midfielder or full back overlaps or underlaps into the wide space to create the 3v2.', 'Forwards adjust quickly to give width (or tuck in); midfielder attacks the gap left; quick combinations; lose marker and turn for 1v1 or set back; midfielders watch forwards'' movements when switching; 1-2 touches; well-timed runs to finish.', '7v7 (incl. GKs)', 14, 14, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 110),
  ('''The X'' passing combination warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 66, 67, NULL, NULL, 'Learn the pass-and-move order of ''The X'' (two crossing diagonal passes) and improve medium-range driven ground passing.', '40 x 40 yard area, 9 cones set as starting gates, full back, winger and striker positions on both sides; at least 11 players, queue at the start gates.', 'From the start, a diagonal pass goes to the winger, who sets back to the full back; the full back plays a second diagonal into the striker, who dribbles back at pace to the start gates. Players rotate one position clockwise, then repeat on the right side rotating anti-clockwise.', 'Cones placed so every pass is over 20 yards; aim for 1 touch (max 2).', 'Add a passive defender: after the third pass the opposite winger runs across to close down the striker, who dribbles at him and plays a one-two before returning to the gates; pressers return to their cone. Begin passive, then make the pressure competitive.', 'Demo on a tactics board first; precise driven ground passes; two movements (check away then show); signal where you want it; one-two timed so the return is neither early nor late.', '11+', 11, NULL, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 120),
  ('Key incision combinations opposed practice', 'combination', 'overload', 'in_possession', 68, 69, NULL, NULL, 'Rehearse the five key incision-phase combinations (''The X'', Classic 1, 2, 3 and Classic 3 variation) against a few live defenders, ending with a shot.', 'Three-quarters of a pitch with 9 cones; ball supply at two start points at the centre backs; blues have a back 4, 3 rotating central mids, 2 wingers and a striker; reds have 2 centre backs at the box and 1 central mid (3v1 in the middle); keeper in goal.', 'A centre back or the coach calls the combination to play, starting from one centre back; blues execute it and attack the goal, with the far winger and full back joining the finish. Players reset and the next attack starts from the other side.', 'Unopposed full backs and wingers limited to 2-3 touches; alternate left and right.', NULL, 'Line up with the incoming ball and pass quickly and precisely; two movements to get free with good timing; pacey passing over 10-20 yards; verbal and hand signals for where you want it.', '10 attackers v 3 + GK', 14, NULL, 'Three-quarters of a pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Incision combinations 8v6 conditioned game', 'phase_of_play', 'overload', 'in_possession', 72, 73, NULL, NULL, 'Use the key incision patterns (X, Classic 1/2/3) under live pressure to break the back line and score.', 'Half pitch; central grid 25 x 20 yards with a wide grid either side; 3 blue rotating mids v 2 red mids in the centre, 3 red defenders at the box, blue wingers in the wide grids and full backs starting outside them; red keeper; blue centre back 5 (or coach) starts.', 'The centre back plays into a rotating midfielder and the game goes live with free movement; blues combine using the patterns (e.g. the 8 is pressed, plays a one-two with the full back, then slips the winger in on a blind-side run) and finish. Reds who win it pass back to the start position.', 'Maximum 1-3 touches to attack with pace.', NULL, 'Explore every pattern and variations; midfield keeps shape while rotating; side-on body shape or set it back under pressure; forwards make two movements; timed runs into the box; pause and name the pattern after a successful combination, then encourage a different one.', '8v6 (+GK)', 15, 15, 'Half pitch; central grid 25 x 20 yards', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('''The Open Gate'' 7v6 half-pitch game', 'phase_of_play', 'overload', 'in_possession', 78, 78, NULL, NULL, 'Explore the ''Open Gate'' movement (striker sets and spins, or makes a curved underlap run, to open space between centre backs for runners).', 'Half pitch: 3 attackers, 2 attacking mids and 2 deeper mids v 4 defenders (incl. centre backs) and 2 defensive mids; goal with keeper; coach as an outlet near halfway.', 'Outline the pattern on a tactics board, walk it through with throw-catch, then play with passive defenders who can track runs but not tackle, and finally fully competitive.', 'Goal from the Open Gate move = 5 points, any other strike = 3 points; defenders who win it hit a long ball to the coach out wide on halfway for 1 point.', 'Throw-catch, then passive defending, then remove the passive condition.', 'Striker stays side-on to see the ball; signal where he wants the return; underlapping run in front of the midfielder; far winger drives in behind the pulled centre back; keep body open and peel away.', '7v6 (+GK)', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('1v1 duel: move defender, shoot', 'one_v_one', 'opposed', 'in_possession', 83, 83, NULL, NULL, 'Dribble to drag the defender one way, then accelerate into the space created and shoot.', '15 x 30 yard grids side by side, a goal at the end of each; attackers queue with balls at the start line, one defender per grid; keepers optional.', 'Attackers take turns to beat the defender and score, giving recovery time and a chance to watch others. Restart with the next attacker when the defender wins it or the ball goes out.', 'Swap roles after 5-10 attempts; players keep count of goals.', 'Add goalkeepers to make finishing harder.', 'Run inside to cut outside (or vice versa) to win half a yard; disguise intentions; try a double bluff; defenders show good technique; Q&A every 5-10 minutes.', '1v1 per grid', 2, NULL, '15 x 30 yards', 27.4, 13.7, NULL, true, false, true, NULL, 160),
  ('2v2 attacking runs to finish', 'one_v_one', 'opposed', 'in_possession', 84, 85, NULL, NULL, 'Use specified attacking runs (blind-side, flat, dummy) in a 2v2 to receive in behind and score.', 'Same 15 x 30 yard grids with goals; attacking pairs take turns against 2 defenders; keepers optional.', 'Pairs attack using a named run to get in behind and finish; restart with the next pair if the defenders win it or the ball goes out. Start with throw-catch to learn each run.', 'Goal from one of the 3 runs = 3 points, other goals 1; no offside at first, add it once ready; swap roles after 5-10 attempts.', 'Variation (same set-up): use the cross-over run (dribbler goes diagonal, partner crosses behind into the space) and the take-over run (partner takes the ball off the dribbler while the first player keeps running). Start with passive defenders, then fully competitive.', 'Eye contact and signals to disguise intentions; timed runs to beat the offside trap; well-weighted pass into the run; place or power finish; follow up secondary chances.', '2v2', 4, NULL, '15 x 30 yards', 27.4, 13.7, NULL, true, false, true, NULL, 170),
  ('Continuous 2v1 duel channels', 'one_v_one', 'overload', 'in_possession', 86, 86, NULL, NULL, 'Combine quickly in repeated 2v1s through zones to create and finish chances.', 'Two grids (10 x 30 and 15 x 30 yards) each split into 3 zones of 10 yards (2v1 zones and a free zone), a goal with keeper at the end of each; 2 attackers v 2 defenders per grid, one defender in each 2v1 zone.', 'Wave practice: pairs attack through their grid to score, then move to the next grid to attack the other way. Restart with the next pair when a defender wins it or the ball goes out.', 'Defenders must stay in their zones; rotate defenders and attackers after 5-10 attempts; pairs keep score.', NULL, 'Diagonal dribble to draw the marker; signal where you want the final pass; read early cues and run early; weighted pass to shoot first time; read the keeper; place vs power; alert to secondary chances.', 'pairs of attackers v 2 defenders per grid + GKs', 8, NULL, '10 x 30 and 15 x 30 yard grids', 27.4, 13.7, NULL, true, true, true, NULL, 180),
  ('3v2/3v3 rotating runs and combinations', 'combination', 'overload', 'in_possession', 87, 90, NULL, NULL, 'Coordinate two-player movements (decoy plus run in behind) to create a scoring chance in 3v2, progressing to 3v3.', 'Same 15 x 30 yard grids with goals; 3 attackers v 2 defenders, option to make it 3v3.', 'Attackers use the named pattern: rotating drop run (one drops to drag a defender, another runs in behind) or rotating lateral run (one runs across to drag a defender, another runs in behind), then finish.', 'Same aims and rules as the previous grid practices (offside added once ready, rotate after 5-10 attempts).', 'Add keepers or cones half a yard inside each post (score between cone and post). Variations in the same grids: flat pass with underlap and diagonal pass with overlap; third man run and classic one-two; back-heel take-over and nutmeg dummy plus spin (start with passive defenders).', 'Selfless decoy runs; read the space early and arrive for the killer pass; eye contact and signals; beat the offside trap; well-weighted passes; secondary chances.', '3v2 / 3v3', 5, 6, '15 x 30 yards', 27.4, 13.7, NULL, true, false, true, NULL, 190),
  ('4v3 drop-set gate and cut runs', 'combination', 'overload', 'in_possession', 91, 91, NULL, NULL, 'Combine 4v3 using drop-set + open the gate and the cut with third man run to score.', 'Grids enlarged to 20 x 30 yards with goals; 4 attackers v 3 defenders.', 'Drop-set + open gate: a player drops and sets back to a third player while the furthest forward moves wide and the passer overlaps into space. Cut with third man run: one cuts inside to drag a marker and receive, the furthest forward double-moves to receive the second pass in behind.', 'Same aims and rules as earlier grid practices.', 'Throw-catch first, then passive defenders, then fully competitive.', 'Decoy runs (cut, drop-set, dummy) to open space; eye contact; striker signals for the final pass; read cues early; beat the offside trap; well-weighted final ball.', '4v3', 7, NULL, '20 x 30 yards', 27.4, 18.3, NULL, true, false, true, NULL, 200),
  ('Finishing combinations with setters, two goals', 'finishing', 'unopposed', 'in_possession', 93, 96, NULL, NULL, 'Rehearse quick combinations with a setter before shooting.', '40 x 50 yards, two large goals with keepers, two groups with balls at opposite ends, 2 setters (B) standing by cones.', 'Both directions at once: player A plays a one-two with setter B, receives, shoots, then joins the group at the other end; next player goes. Change setters after 5-10 attempts.', 'Setters 1 touch where possible; players keep their own score.', 'Variations in the same set-up: set & spin (A passes forward, B sets back, A spins round the cone to receive and shoot, then A becomes setter); third-man run with two setters (A one-twos with B1, B2 spins to receive and shoot, groups take turns not simultaneous); set & one-two (A one-twos with B1, bounces to B2 who one-twos with B1 and shoots).', 'Setter checks away then opens body; pass into the shooter''s run; precise forward one-twos; signal for the return; shoot first time or dribble at speed; place vs power; follow up rebounds; Q&A every 5 minutes.', '2 groups + 2 setters + 2 GKs', 8, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 210),
  ('5v3 central combinations with target players', 'phase_of_play', 'overload', 'in_possession', 97, 98, NULL, NULL, 'Three forwards coordinate runs with two midfielders to break a back three and score through central areas.', 'Half pitch with 7 cones; 5 attackers (2 central mids, 2 wingers, 1 striker) v 3 defenders + keeper; 2 target players near halfway.', 'A central midfielder starts, combining and timing a pass in behind; forwards get 10 attempts then rotate to new forwards; midfielders and target players swap roles each attack. Defenders or keeper who win it play forward to a target player.', '3 points for a goal, 1 for an attempt; start with passive defenders and no offside, then fully competitive with offside.', 'Passive defenders then fully competitive; add offside once successful.', 'Striker sets and spins to open the gate for a winger''s blind-side run; signals for passes; early runs into space; beat the offside trap; weighted passes; eye contact; secondary chances.', '5v3 (+GK) +2 target players', 11, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('''Shoot on sight'' 3-team SSG', 'small_sided_game', 'overload', 'in_possession', 99, 100, NULL, NULL, 'Encourage players to shoot whenever space opens, near or far.', '30 x 30 yards, two large goals with keepers, 3 teams of 4: two play 4v4 inside, the third stand round the outside as support players.', 'Normal game, but the team in possession must pass to an outside player before it can shoot; shoot from anywhere.', 'No offside, no corners, kick-ins instead of throw-ins; add a neutral if numbers are uneven.', 'The 4 outside players join in to make a 7v7 (incl. keepers) with the same shoot-on-sight challenge.', 'Shoot whenever there is half a yard; signal then shoot; set a team-mate for a shot; weighted pass for a first-time finish; one-touch body shape; place vs power; follow up rebounds.', '3 teams of 4 + 2 GKs', 14, 14, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 230),
  ('Crossing: attacking runs to finish 3v2', 'finishing', 'overload', 'in_possession', 104, 105, NULL, NULL, 'Three attackers time near post, back post and penalty-spot runs to finish crosses.', 'Half pitch; 3 attackers v 2 defenders near the box edge with a keeper; 4 build-up positions (1-4) with a marked box for player 2.', '1 passes to 2 in the box, who passes to 3; 3 checks away and passes to 4 while 2 runs forward; 4 one-twos with 2, who gets the ball high on the flank and crosses for the runners. Players follow their pass (1 to 2, 2 to 3, 3 to 4, 4 to start).', 'Restart if defenders win it or ball goes out; change attackers after 10 attempts; no offside at first, add it later.', 'Goal from one of the 3 key runs = 3 points, attempt = 1; players keep score.', 'Lose markers and vary runs (incl. cross-over runs); do not arrive too early; near-post run in line with the post; signal for the cross or cut-back; weighted delivery; eye contact; beat offside; secondary chances.', '3v2 (+GK) + 4 servers', 10, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Continuous 2v1 to 6v6 duels', 'transition', 'overload', 'to_attack', 107, 107, NULL, NULL, 'High-tempo building attack and counter-attack duels that grow from 2v1 to 6v6.', '40 x 40 yards with a large goal and keeper at each end; two teams of 6 numbered players waiting beside the goals.', 'Starts 2v1 to the blues; after a goal or ball out, a new blue dribbles in and one more red joins (3v2), then 4v3, 5v4, 6v5, 6v6. Defenders who win it counter-attack.', 'No offside at first, add it as they succeed.', 'Throw-catch to learn the sequence, then live; add offside.', 'Coordinate runs to create combinations; well-timed runs into space; creativity to isolate defenders; shoot early and from distance; secondary chances.', '2 teams of 6 + 2 GKs', 14, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 250),
  ('Attack v defence 3v1 plus recovering players', 'transition', 'overload', 'in_possession', 108, 109, NULL, NULL, 'Exploit a short-lived overload by attacking at pace before recovering midfielders get back.', 'Half pitch; blue striker v red centre back near the box, 2 blue attacking mids and 2 red defensive mids on halfway; 2 red and 3 blue cones and 2 cone gates on halfway; keeper.', 'A blue midfielder plays into the striker to create 3v1; the 2 red mids must run back 2 yards to halfway before sprinting to recover. Blues combine quickly to score; reds who win it pass through a halfway cone gate (1 goal).', '1-3 touches depending on level; restart with the next pair of midfielders when the ball goes out; change striker often.', '6v2 (+3): add 2 wingers and a No.10 for blue, a second centre back and a third recovering midfielder for red; starting positions at cones, same run-back rule.', 'Striker sets back and the attackers combine at pace; use drop-set, third man, cross-over and lateral runs; check away, receive side-on and turn or set and spin; drift to pull defenders; centre backs delay to let team-mates recover; praise goals and attempts.', '3v1 (+2) +GK; progression 6v2 (+3)', 7, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('6v2 plus 3 recoverers attack v defence', 'transition', 'overload', 'in_possession', 109, 109, 'Progression: Attack v Defence Practice 6 v 2 (+3 Recovering Players)', NULL, 'Attack quickly with a numerical overload and finish before recovering defenders get back.', 'Half pitch plus a strip past halfway with a goal and keeper; blue midfielders, 2 wingers and a striker start at cones near halfway; 2 red centre backs in front of goal and 3 red recovering midfielders at cones on the halfway line, with cone gates on halfway.', 'A blue midfielder passes into a forward to start; 6 blues combine at pace to score. The 3 red midfielders must first run back 2 yards beyond halfway, then sprint to recover and defend. If reds win the ball they try to dribble or pass through a cone gate.', 'Suggest limiting attackers to 1-3 touches.', NULL, 'Striker sets back or checks away and turns; drift wide to open space; use drop-set, third man and cross-over runs; centre backs delay to let help arrive.', '6v2 (+3)', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Turn and volley shooting in pairs', 'finishing', 'unopposed', 'in_possession', 111, 111, 'Shooting Practice: Turn & Volley in Pairs (1 of 4)', NULL, 'Turning and volleying technique for finishing.', 'Pairs lined up outside the penalty area facing a goal with keeper; the player with the ball (A) has his back to goal, partner B faces him.', 'A tosses the ball to B, who heads it back over A''s head; A turns and volleys at goal after at most one bounce. Pairs take turns and swap roles each round.', 'One bounce allowed before the volley; optional scoring out of 3 or 4 attempts.', NULL, 'Open the body on the turn, read the flight, get to the bounce point, don''t lean back, standing foot aimed at target, follow in for rebounds.', 'pairs + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Three-player combination with third man run', 'combination', 'unopposed', 'in_possession', 112, 112, 'Quick Combination Play to Finish with "Third Man Run" (2 of 4)', NULL, 'One-touch third man combination ending in a first-time shot.', 'Half a full pitch, goal and keeper; two groups of attackers (left and right) with positions A, B and C set out by cones near the box, servers in the centre.', 'First player passes into A''s path; A touches forward, passes to B and curves a run into the box. B lays off to C, who passes into A''s run for a first-time shot. Players rotate one position; C retrieves the ball and joins the other side.', 'One-touch passing between A, B and C; alternate sides; swap groups after 5-10 minutes to shoot with both feet.', 'Keep score of goals per player.', 'Arc the run to arrive on time; check keeper position; relaxed, explosive strike without leaning back; follow up rebounds.', '2 groups + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Combination to finish with overlapping run', 'combination', 'unopposed', 'in_possession', 113, 113, 'Variation: Quick Combination Play to Finish with "Overlapping Run" (3 of 4)', NULL, 'Overlap around a team-mate and finish first time from a return pass.', 'As the third man practice but the first pass comes from the side and cones are moved; C starts beside a mannequin at the edge of the box.', 'First pass to A, who touches forward, passes to B and overlaps him into the box; B passes to C, who plays into A''s path for a first-time shot. Rotate positions; C collects ball and joins the other side.', 'Swap left and right groups after 5-10 minutes.', NULL, 'Make the pass the first step of the overlap; choose between placing with the side-foot and power with the laces.', '2 groups + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Combination to finish with set and spin', 'combination', 'unopposed', 'in_possession', 114, 114, 'Quick Combination Play to Finish with "Set and Spin" (4 of 4)', NULL, 'One-two then set-and-spin movement to create a shot.', 'Two groups of attackers either side of the penalty area, positions A, B and C marked with cones and mannequins, goal and keeper.', 'A plays a one-two with B and then passes to C; meanwhile B spins away to receive C''s next pass and shoots. Players move up one position; C retrieves and joins the opposite group.', 'One-touch passing; alternate sides; swap groups after 5-10 minutes.', NULL, 'Arc the spin to get a good shooting angle; time the run; check keeper position; stay over the ball.', '2 groups + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Close ball control dribbling variations', 'technical', 'unopposed', NULL, 119, 119, 'Technical: Close Ball Control Variations', NULL, 'Close control while running with the ball and awareness of others.', '40 x 40 yard square; two groups of 6 or 7 with a ball each, one group on one side and one on an adjacent side.', 'One group dribbles across while the other dribbles up and down, crossing paths. Players work through set techniques: outside-inside one foot, inside-outside, outside right to inside left, double-touch, sole drag sideways, multiple drag-backs.', NULL, 'Repeat each technique on the weaker foot.', 'Head up and aware of players ahead and behind; many touches; rhythm with both feet; drop the shoulder as a body feint.', '2 groups of 6-7', 12, 14, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 320),
  ('T-shape moves to beat practice', 'technical', 'unopposed', NULL, 120, 120, 'Progression: Moves to Beat Opponents (Left & Right) "T Practice"', NULL, 'Develop signature moves to beat an opponent to both left and right.', 'Each player with a ball marks out a T shape: a mannequin as the opponent with cones either side as his reach, a second mannequin at the other end; spacing adjusted to age.', 'Player dribbles at a mannequin and does a move past it to the left (10 o''clock) or right (2 o''clock), loops round the far cone and repeats past the other mannequin, alternating sides.', NULL, 'After about 3 minutes rest and have players demo their signature moves to the group.', 'Pace with close control; feints and step-overs; move at the right distance; change of pace; quick feet; both feet; double touches and drag-backs.', 'individual', NULL, NULL, NULL, NULL, NULL, 10.0, false, false, true, NULL, 330),
  ('Continuous moves to beat around poles', 'technical', 'unopposed', NULL, 121, 121, 'Progression: Moves to Beat Opponents in a Continuous Practice', NULL, 'Dribble at speed and beat a pole with a move, then pass on, continuously.', '20 x 40 yard area split into lanes, groups of 3 with 1 ball; two poles or cones per lane across the middle; two players at one end, one at the other.', 'First player dribbles forward, does a move outside one of the poles, then passes to the player at the far end and follows to swap ends. That player repeats back the other way.', NULL, NULL, 'Same as the T practice: speed, feints, change of pace, both feet.', 'groups of 3', 3, NULL, '20 x 40 yards', 36.6, 18.3, NULL, false, false, true, NULL, 340),
  ('Gladiator contest continuous 1v1 to goal', 'one_v_one', 'opposed', 'in_possession', 122, 122, 'Progression: Continuous 1 v 1 Duels & Finishing: "Gladiator Contest"', NULL, 'Beat a defender 1v1 and finish past the keeper.', 'Half pitch with goal and keeper; red defenders with balls on the goal line either side of the goal, blue attackers lined up near halfway.', 'A defender passes long to an attacker and closes him down; the attacker drives forward, beats him and shoots. When the ball is won or goes out, the next defender serves the next attacker.', 'Keep count of goals; swap roles after 10 minutes.', NULL, 'Positive first touch forward, shoot early, move the defender off your line, assess keeper, place vs power, follow up.', 'equal groups + GK', NULL, NULL, 'half pitch', NULL, NULL, 20.0, true, true, true, NULL, 350),
  ('2v2 hide and seek keep-ball', 'one_v_one', 'opposed', 'in_possession', 123, 123, 'Moves to Beat Opponents in a 2 v 2 "Hide & Seek" Practice', NULL, 'Shield and beat an opponent 1v1 to open a passing lane to a team-mate.', '15 x 15 yard grids, 2v2 in each; enough grids for everyone.', 'The player on the ball must keep it while his team-mate deliberately hides behind an opponent so he cannot be found. The dribbler has to beat his man to open a channel, then passes and the pair swap roles.', NULL, NULL, 'Close control at pace, feints, step-overs, change of pace, quick turns, both feet, drag-backs, own signature moves.', '2v2', 4, 4, '15 x 15 yards', 13.7, 13.7, NULL, false, false, false, NULL, 360),
  ('Keep-ball outnumbered 2v3 or 2v4', 'one_v_one', 'opposed', 'in_possession', 124, 125, 'Progression: Close Control and Moves to Beat Opponents with a Numerical Disadvantage (2 v 3 / 2 v 4)', NULL, 'Keep possession under defender overload by shielding and beating opponents.', '20 x 20 yard area; 2 attackers against 2, 3 or 4 defenders depending on ability.', 'The 2 attackers try to keep the ball, using moves to beat defenders where needed. Rotate roles every 2-3 minutes.', '1 point for keeping the ball 10-20 seconds or for each successful move past a defender.', 'Start with 2v2 and add defenders; begin with shielding technique (knees bent, legs apart, ball on safe side, arm to hold off) and drag-back turns.', 'Close down while keeping control; feints; right distance; move opponent outside to cut in; step-overs, change of pace, acceleration, double touch, sole drag, drag-backs.', '2v3 / 2v4', 5, 6, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 370),
  ('Running with the ball diagonal box game', 'positional_game', 'opposed', 'in_possession', 126, 127, 'Progression: ''Running With The Ball'' in a Directional 7 v 7 Game', NULL, 'Receive in space and run with the ball to advance play.', '50 x 50 yard area with a cone box in each corner (two per team, diagonally opposite); 7v7 or 6v6, neutral added for odd numbers.', 'Teams try to get the ball from one of their boxes to the diagonally opposite one, by running with it whenever space allows; on success they keep the ball and attack the other diagonal.', NULL, 'Reward one player carrying it box to box alone; medals for best runs; optional no-passing condition.', 'Head up before receiving, signal for the pass, directional first touch forward, first touch is first stride, ball a yard ahead at speed, use laces, quick feet to beat a player.', '7v7 or 6v6', 12, 15, '50 x 50 yards', 45.7, 45.7, NULL, false, false, true, NULL, 380),
  ('7v7 running with the ball game', 'small_sided_game', 'opposed', 'in_possession', 128, 128, 'Progression: ''Running With The Ball'' & ''Moves to Beat Opponents'' in a 7 v 7 Small Sided Game', NULL, 'Run with the ball into space and beat players in advanced areas in a match.', '40 x 60 yard area or half pitch with two goals and keepers; teams in a 2-2-2 shape.', 'Coach serves a ball into the middle for teams to compete; both teams try to score focusing on running with the ball, with players rotating and covering for runners from deep.', 'Coach restarts when the ball goes out.', NULL, 'Forward runs with the ball when space is on; create space for team-mates; use a move to beat in advanced areas.', '7v7 incl GKs', 14, 14, '40 x 60 yards', 54.9, 36.6, NULL, true, true, true, NULL, 390),
  ('Directional first touch passing in pairs', 'passing_unopposed', 'unopposed', NULL, 130, 130, 'Receiving with a Directional First Touch + Controlled Passing (Unopposed)', NULL, 'Directional first touch and accurate return pass.', 'Pairs in 10 x 20 yard grids, each player in a 2 x 2 yard box with a red cone behind it.', 'Players pass along the ground box to box; after each pass the passer drops round his red cone and returns. The receiver takes a directional first touch out to left or right of his box and returns the pass with the second touch between the front cones.', 'Two touches; optional points per successful two-touch execution.', NULL, 'Rhythm, accuracy between the cones, touch out of the box.', 'pairs', 2, NULL, '10 x 20 yards', 18.3, 9.1, 10.0, false, false, false, NULL, 400),
  ('Directional first touch away from pressure', 'passing_opposed', 'passive', NULL, 131, 131, 'Receiving with a Directional First Touch + Controlled Passing with Pressure', NULL, 'Read where pressure comes from and take the first touch away from it.', 'As the unopposed version: pairs in 10 x 20 yard grids with 2 x 2 yard boxes.', 'After passing, the passer makes an arced run to press either the left or right side of his partner, who must take a directional touch out of the box away from that side, then dribble and pass back. Players swap ends and repeat.', NULL, NULL, 'Pass on the ground with pace and weight; line up with the ball; touch out of the box away from pressure; accurate second-touch pass.', 'pairs', 2, NULL, '10 x 20 yards', 18.3, 9.1, NULL, false, false, false, NULL, 410),
  ('Opening up to receive square circuit', 'passing_unopposed', 'unopposed', NULL, 132, 132, 'Progression: Exploring "Opening Up" to Receive & One-Touch Passing', NULL, 'Move out of a box and open the body to receive, then pass on.', '20 x 20 yard area made of two grids with 4 coned boxes and 4 players; 3 start inside the boxes, 1 outside.', 'Ball is passed round the outside of the area anti-clockwise; each player makes a curved run out of his box with an open body to receive, controls and passes on to the next.', 'Two touches; right foot anti-clockwise, left foot clockwise; change direction after 5-10 minutes.', 'Open up and pass with the first touch.', 'Time the movement out of the box, half-turned body, eye contact to call the pass, pass into space ahead of the next player, weight and accuracy.', '4', 4, 4, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 420),
  ('5v5v5 three zone possession warm-up', 'possession', 'opposed', 'in_possession', 133, 133, '5 v 5 v 5 Three Zone Possession Warm Up Game', NULL, 'Short passing to keep the ball and longer passes to switch over a middle zone.', '20 x 30 yard area in 3 equal zones; 3 teams of 4 or 5, one in each zone.', 'An end team makes 5 passes, then plays through or over the middle team to the far end team. The middle team sends 1 (then 2) players to press and win the ball. A team that loses the ball or puts it out goes into the middle.', '2 or 3 touches depending on ability.', 'Increase from 1 to 2 pressing opponents once passing tempo is good.', 'Use full width and depth, angles of support, open body and directional touch, quick short passes, well-weighted long passes, receivers keep moving to open channels.', '3 teams of 4-5', 12, 15, '20 x 30 yards', 27.4, 18.3, NULL, false, false, true, NULL, 430),
  ('Triangle pass and move square pattern', 'passing_unopposed', 'unopposed', NULL, 134, 136, 'One / Two-Touch Technical Pass & Move Practice (1), with (2) and (3)', NULL, 'One and two-touch passing and following the pass for advanced players.', '25 x 25 yard square with a red-cone triangle in the centre; at least 8 players at the corners and triangle points.', 'Player 1 passes to 2 and follows; 2 to 3 at the bottom of the triangle; 3 sets back to 2, who plays first time to 4b; 4b sets to 3, who has spun and plays wide to the far corner (5). Everyone follows their pass; then the pattern repeats the other way using 4a.', 'One touch if possible, otherwise two.', '(2) longer pattern where 2 plays straight into 4b, who sets to 3 to play wide; (3) harder version with 25-yard diagonal passes from corner to corner, lofted if players struggle.', 'Ground passes with pace, weight for a first-time pass, half-turned body, signal which foot, centre players open a channel, pass is first step of the run, tempo.', '8+', 8, NULL, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 440),
  ('Free-choice pass and move square', 'passing_unopposed', 'unopposed', NULL, 137, 137, 'One / Two-Touch Technical Pass & Move Practice (4)', NULL, 'Awareness and decision making in a pass and move circuit.', '25 x 25 yard square with a 15 x 15 yard square in the centre; 9-12 players on the corners of both squares.', 'Players choose who to pass to and always follow their pass to that position; corner players rotate to keep the flow.', 'One touch if possible, otherwise two.', 'Add a second ball once tempo is good.', 'Eye contact and communication, ground passes, half-turned body, signal which foot, open channels for through passes.', '9-12', 9, 12, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 450),
  ('6 plus 4 corners v 4 keep-ball', 'positional_game', 'overload', 'in_possession', 138, 138, 'Progression: 6 (+4) v 4 Possession Practice with Rotating Corner Players', NULL, 'Keep possession and find the corner players after building passes.', '25 x 25 yard square with a small box in each corner; 6-7 blue players inside plus 4 corner players v 4 red defenders.', 'Blues aim to play into all four corners without losing the ball; a corner may only be played to after 2 passes without a defender touching. The player passing in swaps with the corner player. If reds win it they try to make 6 passes.', '1 point per corner reached; reds 1 point for 6 consecutive passes; corner players not involved for reds.', NULL, 'Eye contact, move after passing to find a support angle, half-turned body, signal which foot, decoy runs to open channels.', '6 (+4) v 4', 14, 15, '25 x 25 yards', 22.9, 22.9, NULL, false, false, true, NULL, 460),
  ('2 plus 8 v 4 split rondo', 'rondo', 'overload', 'in_possession', 139, 139, 'Advance the Play Through Pressure in a 2 (+8) v 4 Rondo', NULL, 'Play through central players under pressure to move the ball across.', '25 x 25 yard area with a 20 x 20 yard square inside; 8 blue players outside, 2 blue and 4 red inside.', 'Outside players move the ball from one side to the other via the 2 central players; they may pass among themselves but only score by going through a central player. If reds win it they try 8 passes in the middle.', '1, 2 or 3 touches; central players encouraged to play one touch; 1 point per switch through the middle, reds 1 point for 8 passes.', NULL, 'Quick ground passes, central players check away before receiving and signal, bounce passes first time, everyone moves to support.', '2 (+8) v 4', 14, 14, '25 x 25 yards', 22.9, 22.9, NULL, false, false, true, NULL, 470),
  ('7v7 switching play to corner targets', 'positional_game', 'opposed', 'in_possession', 140, 140, 'Progression: Switching Play Against High Intensity Pressure in a Possession Game with Target Players', NULL, 'Switch play from one target to the other under pressure.', '40 x 50 yard area, 7v7 (or 6v6) plus a neutral; cone gates in each corner with 2 target players per team in diagonally opposite corners.', 'Teams try to move the ball from one of their target players to the other; whoever passes into a target swaps places with him.', '2 or 3 touches.', 'Start on the ground, then allow longer lofted switches.', 'Width and depth, quick triangles, penetrating passes, driven ground and lofted passes, signal, first-time or open up and pass.', '7v7+1', 13, 15, '40 x 50 yards', 45.7, 36.6, NULL, false, false, true, NULL, 480),
  ('4v4 plus 5 possession to shoot', 'possession', 'overload', 'in_possession', 141, 141, 'Creating Space to Finish in a 4 v 4 (+5) Possession Practice', NULL, 'Create space and angles to get shots off, combining with support when the shot is not on.', '30 x 40 yard area with one goal and keeper; 3 teams of 4: two teams inside, the third on the outside, plus 1 neutral inside.', 'An outside player passes in; the team in possession uses the neutral and outside players to work a shot. If defenders win the ball they become attackers but must first play to an outside or neutral player.', 'Neutral and outside players cannot score; 3-minute games, teams rotate so each plays 2 inside; 2 or 3 touches.', NULL, 'Use width and depth, quick ground combinations when no shot, check away and signal, play to striker and follow for a set and shoot.', '4v4 (+5) + GK', 14, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, true, true, NULL, 490),
  ('Four zone possession with two-way press', 'positional_game', 'opposed', 'in_possession', 142, 142, 'Playing Through the Thirds with Two-Way Pressure in a Zonal Possession Game', NULL, 'Pass through zones to team-mates in other zones against pressing.', '25 x 50 yard area in 4 equal zones; 8v8 (or 6v6) including keepers, each team split into groups of 3 or 4 across different zones.', 'Team in possession makes 2-3 passes then plays to team-mates in another zone; defenders press with 2 players from neighbouring zone(s), 1 from each side if the ball is in an inner zone. Win the ball and do the same; losers press to win it back.', 'Ground passes; 2 or 3 touches; ball out of play goes to opponents.', NULL, 'Width and depth in each zone, angles, open body, quick short passes, driven passes between zones, players in other zones stay mobile.', '8v8 or 6v6', 12, 16, '25 x 50 yards', 45.7, 22.9, NULL, false, true, true, NULL, 500),
  ('6v3 zonal game through the thirds', 'phase_of_play', 'overload', 'in_possession', 143, 143, 'Playing Through the Thirds in a 6 v 3 / 8 v 4 Zonal Game', NULL, 'Build through central zones with ground passes before entering the final zone to score.', '30 x 50 yard area in 5 zones of 10 yards with a goal and keeper at each end; 2v1 overload for blue in each of the 3 central zones.', 'Keeper passes to a blue in the nearest zone; blues must find a player in each central zone before entering the final zone to shoot. Back passes allowed.', '2 or 3 touches; rotate roles often.', '2v2 in each zone, or widen and play 3v2 for the attackers.', 'Use zone width for the 2v1, quick driven ground passes, check away and signal, first time or two touches, open up to receive.', '6v3 (8v4) + 2 GK', 11, 14, '30 x 50 yards', 45.7, 27.4, NULL, true, true, true, NULL, 510),
  ('7v7 side zones crossing game', 'small_sided_game', 'opposed', 'in_possession', 144, 144, 'Possession, Crossing & Finishing in a Small Sided Game with Side Zones', NULL, 'Switch play to a winger and finish from crosses and cut-backs.', '50 x 60 yard area with halfway line and 2 wide channels; 2v2 in each half and 2 unopposed wingers per team in the channels; goals and keepers.', 'Keeper starts; teams must play through a winger (2 touches max) before scoring. When the winger receives, one player from the defensive half joins the attack to make 3v2.', 'Winger limited to 2 touches; central players 2 or 3 touches; rotate wide players.', 'Far-side winger also attacks the back post (4v2).', 'Drag markers away, release wide quickly and support, near post / far post / penalty spot runs, winger reads runs, adjust runs if cross is delayed.', '7v7 incl GKs', 14, 14, '50 x 60 yards', 54.9, 45.7, NULL, true, true, true, NULL, 520),
  ('Short corner sole roll and scoop', 'set_piece', 'opposed', 'set_piece', 147, 147, 'Short Corner Routine: "Sole Roll & Scoop"', NULL, 'Short corner using disguise to draw defenders out and create a delivery chance.', 'Attacking corner: 2 attackers by the ball, a player covering the D, full back in support, 2 defenders held back, rest in the box.', 'One corner taker rolls the ball forward with his sole and runs round or between the 2 pressing opponents; his team-mate scoops it over them into his path. He then cuts back to the penalty spot / D, plays to the near post, or chips to the back post for headers.', NULL, NULL, 'Disguise, coordinated movement in the box, keep defensive cover for security.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Short corner set and spin', 'set_piece', 'opposed', 'set_piece', 148, 148, 'Short Corner Routine: "Set & Spin"', NULL, 'Short corner using a lay-off and spin to escape markers.', 'Attacking corner set-up as the sole roll routine; No.8 starts away and runs late towards the corner flag.', 'Taker plays short into No.8, who sets it back and spins around or between the two pressing defenders; taker chips the return into his run. No.8 then cuts back, plays near post or chips to back post.', NULL, NULL, 'Eye contact and disguise; quick link-up.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Short corner one-two set and shoot', 'set_piece', 'opposed', 'set_piece', 149, 149, 'Short Corner Routine: "One-Two Set & Shoot"', NULL, 'Short corner one-two finishing with a shot from the edge of the box.', 'Attacking corner; No.8 comes short from the box edge, No.10 starts in the cluster, No.4 near the box edge, full back advanced, centre backs cover.', 'Taker passes to No.8, who sets it back; No.4 makes a decoy run inside to drag his marker; No.10 arcs into the space and the taker weights a pass for him to shoot first time from the edge of the area.', NULL, NULL, 'Starting positions understood; shooter arcs run and signals; time the break-out on the return pass.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Short corner one-two set and cross', 'set_piece', 'opposed', 'set_piece', 150, 150, 'Short Corner Routine: "One-Two Set & Cross"', NULL, 'Short corner variation ending in a shorter diagonal cross to the back post.', 'As the one-two set and shoot routine.', 'After the one-two, the taker plays to No.10 arcing to the box edge, who lofts a targeted ball to the back post (or drives it along the ground to the penalty spot) for runners.', NULL, 'Short corner practice: realistic numbers, explore 2-3 options with passive defenders first, then fully competitive.', 'Shorter cross suits youth players; team-mates time runs into space to finish first time; use tactics board and Q&A to assign roles.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Free kick edge of box decoy arc', 'set_piece', 'opposed', 'set_piece', 151, 151, 'Free Kick Routine on the Edge of the Box', NULL, 'Wide free kick near the box using decoys and a square pass for a strike.', 'Free kick wide of the 18-yard box; a group outside the box looks ready to attack a back-post cross; a designated shooter at the back of the group; extra wide decoy optional.', 'Taker disguises a cross; group runs forward to drag markers; instead the taker plays a weighted ground pass across the edge of the box for the arcing shooter to strike first time.', NULL, 'Free kick practice: 7v7 (+GK), switch roles, best goals from 5 attempts.', 'Disguise, shooter times run and checks keeper, others follow up secondary chances.', '7v7 + GK', 15, 15, NULL, NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Free kick cross-over decoy split wall', 'set_piece', 'opposed', 'set_piece', 152, 152, 'Free Kick Routine: "Cross-Over Decoy"', NULL, 'Split the wall with crossing decoy runs and shoot through the gap.', 'Central free kick; 4 players around the ball (A, B, C, D), 3 more attackers on the far side of the box, 2 centre backs back.', 'A plays short to C, who stops it with his sole; A and B make overlapping diagonal decoy runs to pull the wall apart; D feints to pass to them then shoots through any gap. Far-side attackers drive in for rebounds.', NULL, NULL, 'Fast decoy runs in front of the shooter; C and D stay on box edge to press if lost; centre backs hold deep.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Free kick mix-up disguise tap and spin', 'set_piece', 'opposed', 'set_piece', 153, 153, 'Free Kick Routine: "Mix-Up Disguise"', NULL, 'Disguised free kick to get round the end of the wall.', 'Free kick at the edge of the box; A and B stand with backs to goal in front of the ball hiding it; C lines up to shoot; cluster of attackers at the back post as decoys.', 'As C runs up, A slips a short sideways pass across B, who spins and takes a short run to curl the ball round the end of the wall.', NULL, 'For mischief, A and B fake an argument and A pretends to push B aside before tapping the pass.', 'Check wall position; well-weighted pass; shoot with power and precision on the turn.', 'full team', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 590)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
